// Renders brand/dist/<name>/Tokens.swift from resolved tokens.
//
// Layout of the generated file:
//   1. `<P>Tokens` — raw values in plain Swift (Foundation only, compiles on Linux),
//   2. SwiftUI extensions (Color, CGFloat, Font, Animation, Material, View) behind
//      `#if canImport(SwiftUI)`,
//   3. haptics: UIKit generators on iOS, WatchKit on watchOS.
// Apps only see semantic colours; core ramps and palettes stay in the tokens and CSS.
// Written with the HandCAD names (HC / hc) and re-prefixed at the end (core: BT / bt).
import { parseHex } from './color.mjs';

const pascal = (parts) =>
  parts
    .flatMap((p) => String(p).split('-'))
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('');
const camel = (parts) => {
  const p = pascal(parts);
  return p.charAt(0).toLowerCase() + p.slice(1);
};



/** The Swift API a token surfaces as, or null when it has no Swift form. */
export function swiftName(t, prefix = 'HC') {
  return reprefix(swiftNameHC(t), prefix);
}

function swiftNameHC(t) {
  const [g, ...rest] = t.path;
  if (g === 'color') return t.modeDependent ? `Color.hc${pascal(rest)}` : null; // core ramps stay out of apps
  if (g === 'palette') return null; // palettes never enter an app's chrome
  if (g === 'font' && rest[0] === 'family') return `HCTokens.Fonts.${camel(rest.slice(1))}`;
  if (['space', 'radius', 'layout', 'border', 'device', 'icon', 'focus'].includes(g)) {
    return t.type === 'dimension' ? `CGFloat.hc${pascal(t.path)}` : null;
  }
  if (g === 'opacity') return `CGFloat.hc${pascal(t.path)}`; // web-only groups (breakpoint, grid, layer) and mark have no Swift form
  if (g === 'type') return `Font.hc${pascal(rest)}`;
  if (g === 'motion') return `Animation.hc${pascal([rest[0]])}(reduceMotion:)`;
  if (g === 'elevation') return `HCTokens.Elevation.level${rest[0]}`;
  if (g === 'material') return `Material.hc${pascal(rest)}`;
  if (g === 'feedback-haptic') return `HCHaptic.${camel(rest)}`;
  return null;
}

const px = (v) => {
  const m = /^(-?[\d.]+)px$/.exec(String(v));
  if (!m) throw new Error(`Expected a px dimension, got ${v}`);
  return Number(m[1]);
};
const ms = (v) => {
  const m = /^([\d.]+)ms$/.exec(String(v));
  if (!m) throw new Error(`Expected a ms duration, got ${v}`);
  return Number(m[1]) / 1000;
};
const num = (n) => (Number.isInteger(n) ? `${n}` : `${+n.toFixed(4)}`);
const doc = (t, indent) => (t.description ? `${indent}/// ${t.description.replace(/\n/g, ' ')}\n` : '');

function rgba(hex) {
  const c = parseHex(hex);
  const h = (n) => `0x${n.toString(16).toUpperCase().padStart(2, '0')}`;
  return `RGBA(${h(c.r)}, ${h(c.g)}, ${h(c.b)}${c.a8 === 255 ? '' : `, ${h(c.a8)}`})`;
}

const TEXT_STYLES = {
  largeTitle: '.largeTitle',
  title: '.title',
  title2: '.title2',
  title3: '.title3',
  headline: '.headline',
  body: '.body',
  callout: '.callout',
  subheadline: '.subheadline',
  footnote: '.footnote',
  caption: '.caption',
  caption2: '.caption2',
};
const WEIGHTS = { 400: '.regular', 500: '.medium', 600: '.semibold', 700: '.bold' };

/** Swaps the HC / hc prefix for a sub-brand's own (identity for HandCAD). */
export function reprefix(text, prefix = 'HC') {
  if (text == null || prefix === 'HC') return text;
  const lower = prefix.toLowerCase();
  return text.replace(/\bHC(?=Tokens|Haptic)/g, prefix).replace(/\bhc(?=[A-Z(])/g, lower);
}

export function renderSwift({ tokens, sb }, config, prefix = 'HC') {
  return reprefix(renderSwiftHC({ tokens, sb }, config), prefix);
}

function renderSwiftHC({ tokens, sb }, config) {
  const ref = config.referenceMode;
  const by = (pred) => tokens.filter(pred);
  const colors = by((t) => t.path[0] === 'color' && swiftName(t));
  const dims = by((t) => swiftName(t)?.startsWith('CGFloat.'));
  const types = by((t) => t.path[0] === 'type');
  const families = by((t) => t.path[0] === 'font' && t.path[1] === 'family');
  const familyOf = (t) => {
    const ref = t.original?.fontFamily;
    const m = /^\{font\.family\.([\w-]+)\}$/.exec(ref ?? '');
    if (!m) throw new Error(`${t.key}: fontFamily must reference a font.family token, got ${ref}`);
    return camel([m[1]]);
  };
  const shadows = by((t) => t.path[0] === 'elevation');
  const materials = by((t) => t.path[0] === 'material');
  const haptics = by((t) => t.path[0] === 'feedback-haptic');
  const motionGroups = [...new Set(by((t) => t.path[0] === 'motion').map((t) => t.path[1]))];
  const motion = (g, leaf) => tokens.find((t) => t.key === `motion.${g}.${leaf}`);

  const L = [];
  const add = (s = '') => L.push(s);

  add(`// Tokens.swift — GENERATED by Style Dictionary from brand/tokens/${sb.isCore ? '' : ` + brand/subbrands/${sb.name}/`} (W3C DTCG). Do not edit.`);
  add(`// Beatham ${sb.isCore ? 'core' : `sub-brand: ${sb.manifest.label}`}. Regenerate: npm run brand:build${sb.isCore ? '' : ` -- --subbrand ${sb.name}`} · Config: brand/brand.config.js`);
  add('// Modes: dark (reference, dark-first), high-contrast dark, light, high-contrast light.');
  add('// swiftlint:disable all');
  add();
  add('import Foundation');
  add();
  add(`/// Raw Beatham design-token values (${sb.isCore ? 'core' : sb.manifest.label}). Platform-neutral (no SwiftUI/UIKit) so it also builds on Linux.`);
  add('public enum HCTokens {');
  add('    /// An sRGB colour as 8-bit channels.');
  add('    public struct RGBA: Sendable, Hashable {');
  add('        public let red: UInt8, green: UInt8, blue: UInt8, alpha: UInt8');
  add('        public init(_ red: UInt8, _ green: UInt8, _ blue: UInt8, _ alpha: UInt8 = 0xFF) {');
  add('            self.red = red; self.green = green; self.blue = blue; self.alpha = alpha');
  add('        }');
  add('    }');
  add();
  add('    /// A semantic colour resolved for every mode.');
  add('    public struct ModeColor: Sendable, Hashable {');
  add('        public let dark: RGBA, highContrastDark: RGBA, light: RGBA, highContrastLight: RGBA');
  add('        public func resolve(dark isDark: Bool, highContrast: Bool) -> RGBA {');
  add('            isDark ? (highContrast ? highContrastDark : dark) : (highContrast ? highContrastLight : light)');
  add('        }');
  add('    }');
  add();
  add('    public enum Colors {');
  for (const t of colors) {
    const n = camel(t.path.slice(1));
    add(doc(t, '        ').trimEnd() || undefined);
    add(
      `        public static let ${n} = ModeColor(dark: ${rgba(t.raw.dark)}, highContrastDark: ${rgba(t.raw['high-contrast-dark'])}, light: ${rgba(t.raw.light)}, highContrastLight: ${rgba(t.raw['high-contrast-light'])})`,
    );
  }
  add('    }');
  add();
  add('    /// Dimensions in points (4 pt grid); opacity steps are 0–1.');
  add('    public enum Dimensions {');
  for (const t of dims) {
    add(doc(t, '        ').trimEnd() || undefined);
    add(`        public static let ${camel(t.path)}: Double = ${num(t.path[0] === 'opacity' ? Number(t.raw[ref]) : px(t.raw[ref]))}`);
  }
  add('    }');
  add();
  add('    /// A font family. `faces` maps a weight (400, 500, 600, 700) to the PostScript name of a bundled');
  add('    /// face (brand/fonts, SIL OFL 1.1); empty for the system font. `fallbackMonospaced` picks the');
  add('    /// system design (SF Mono or SF Pro) used when no face is registered.');
  add('    public struct FontFamily: Sendable, Hashable {');
  add('        public let name: String, faces: [Int: String], files: [String], fallbackMonospaced: Bool');
  add();
  add('        /// The bundled face for a weight: the exact weight, else the nearest heavier, else the heaviest.');
  add('        public func face(weight: Int) -> String? {');
  add('            let weights = faces.keys.sorted()');
  add('            guard let pick = weights.first(where: { $0 >= weight }) ?? weights.last else { return nil }');
  add('            return faces[pick]');
  add('        }');
  add('    }');
  add();
  add('    /// The four families: SF Pro text (SF Compact on watchOS), Instrument Sans titles, JetBrains Mono numbers, Bitcount Single hero numerals.');
  add('    public enum Fonts {');
  for (const t of families) {
    const ext = t.extensions?.beatham ?? {};
    const faces = Object.entries(ext.faces ?? {});
    const files = (ext.files ?? []).map((f) => `"${f.split('/').pop()}"`);
    add(doc(t, '        ').trimEnd() || undefined);
    add(
      `        public static let ${camel(t.path.slice(2))} = FontFamily(name: "${t.raw[ref][0]}", faces: [${faces.length ? faces.map(([w, n]) => `${w}: "${n}"`).join(', ') : ':'}], files: [${files.join(', ')}], fallbackMonospaced: ${ext.fallback === 'monospaced'})`,
    );
  }
  add('        /// Every bundled font file, for the app target and Info.plist `UIAppFonts` (files in brand/fonts).');
  add(`        public static let bundledFiles: [String] = [${families.map((t) => `${camel(t.path.slice(2))}.files`).join(', ')}].flatMap { $0 }`);
  add('    }');
  add();
  add('    /// A Dynamic Type style. `size`/`lineHeight` are the defaults at the Large content size.');
  add('    public struct TextStyle: Sendable, Hashable {');
  add('        public let textStyle: String, size: Double, lineHeight: Double, weight: Int, letterSpacing: Double, monospaced: Bool');
  add('        public let family: FontFamily');
  add('    }');
  add();
  add('    public enum Typography {');
  for (const t of types) {
    const v = t.raw[ref];
    const ext = t.extensions?.beatham ?? {};
    if (!TEXT_STYLES[ext.textStyle]) throw new Error(`${t.key}: unknown textStyle ${ext.textStyle}`);
    if (!WEIGHTS[v.fontWeight]) throw new Error(`${t.key}: unsupported weight ${v.fontWeight}`);
    add(doc(t, '        ').trimEnd() || undefined);
    add(
      `        public static let ${camel(t.path.slice(1))} = TextStyle(textStyle: "${ext.textStyle}", size: ${num(px(v.fontSize))}, lineHeight: ${num(ext.lineHeightPt)}, weight: ${v.fontWeight}, letterSpacing: ${num(px(v.letterSpacing))}, monospaced: ${ext.tabular ? 'true' : 'false'}, family: Fonts.${familyOf(t)})`,
    );
  }
  add('    }');
  add();
  add('    /// A motion with its Reduce Motion variant. Control points are a cubic Bézier.');
  add('    public struct Motion: Sendable, Hashable {');
  add('        public let duration: Double, reducedDuration: Double');
  add('        public let c1x: Double, c1y: Double, c2x: Double, c2y: Double');
  add('        public func duration(reduceMotion: Bool) -> Double { reduceMotion ? reducedDuration : duration }');
  add('    }');
  add();
  add('    public enum Motions {');
  for (const g of motionGroups) {
    const d = motion(g, 'duration');
    const r = motion(g, 'duration-reduced');
    const e = motion(g, 'easing');
    const [c1x, c1y, c2x, c2y] = e.raw[ref];
    add(doc(d, '        ').trimEnd() || undefined);
    add(
      `        public static let ${camel([g])} = Motion(duration: ${num(ms(d.raw[ref]))}, reducedDuration: ${num(ms(r.raw[ref]))}, c1x: ${num(c1x)}, c1y: ${num(c1y)}, c2x: ${num(c2x)}, c2y: ${num(c2y)})`,
    );
  }
  add('    }');
  add();
  add('    public struct Shadow: Sendable, Hashable {');
  add('        public let color: RGBA, x: Double, y: Double, blur: Double, spread: Double');
  add('    }');
  add();
  add('    public enum Elevation {');
  for (const t of shadows) {
    const v = t.raw[ref];
    add(doc(t, '        ').trimEnd() || undefined);
    add(
      `        public static let level${t.path[1]} = Shadow(color: ${rgba(v.color)}, x: ${num(px(v.offsetX))}, y: ${num(px(v.offsetY))}, blur: ${num(px(v.blur))}, spread: ${num(px(v.spread))})`,
    );
  }
  add('    }');
  add();
  add('    public struct Haptic: Sendable, Hashable {');
  add('        public enum Generator: String, Sendable { case impact, notification, selection }');
  add('        public let generator: Generator, style: String');
  add('    }');
  add();
  add('    public enum Haptics {');
  for (const t of haptics) {
    const v = t.raw[ref];
    add(doc(t, '        ').trimEnd() || undefined);
    add(`        public static let ${camel(t.path.slice(1))} = Haptic(generator: .${v.generator}, style: "${v.style}")`);
  }
  add('    }');
  add('}');
  add();

  // ---------- SwiftUI ----------
  add('#if canImport(SwiftUI)');
  add('import SwiftUI');
  add();
  add('public extension Color {');
  add('    /// A colour that follows light/dark and Increase Contrast.');
  add('    init(hcMode c: HCTokens.ModeColor) {');
  add('        #if os(watchOS)');
  add('        // watchOS is always dark (and true black behind everything): the dark value.');
  add('        let v = c.dark');
  add('        self.init(.sRGB, red: Double(v.red) / 255, green: Double(v.green) / 255, blue: Double(v.blue) / 255, opacity: Double(v.alpha) / 255)');
  add('        #elseif canImport(UIKit)');
  add('        self.init(uiColor: UIColor { traits in');
  add('            let v = c.resolve(dark: traits.userInterfaceStyle == .dark, highContrast: traits.accessibilityContrast == .high)');
  add('            return UIColor(red: CGFloat(v.red) / 255, green: CGFloat(v.green) / 255, blue: CGFloat(v.blue) / 255, alpha: CGFloat(v.alpha) / 255)');
  add('        })');
  add('        #elseif canImport(AppKit)');
  add('        self.init(nsColor: NSColor(name: nil) { appearance in');
  add('            let match = appearance.bestMatch(from: [.aqua, .darkAqua, .accessibilityHighContrastAqua, .accessibilityHighContrastDarkAqua])');
  add('            let isDark = match == .darkAqua || match == .accessibilityHighContrastDarkAqua');
  add('            let isHC = match == .accessibilityHighContrastAqua || match == .accessibilityHighContrastDarkAqua');
  add('            let v = c.resolve(dark: isDark, highContrast: isHC)');
  add('            return NSColor(srgbRed: CGFloat(v.red) / 255, green: CGFloat(v.green) / 255, blue: CGFloat(v.blue) / 255, alpha: CGFloat(v.alpha) / 255)');
  add('        })');
  add('        #else');
  add('        let v = c.dark');
  add('        self.init(.sRGB, red: Double(v.red) / 255, green: Double(v.green) / 255, blue: Double(v.blue) / 255, opacity: Double(v.alpha) / 255)');
  add('        #endif');
  add('    }');
  add();
  for (const t of colors) {
    add(doc(t, '    ').trimEnd() || undefined);
    add(`    static let hc${pascal(t.path.slice(1))} = Color(hcMode: HCTokens.Colors.${camel(t.path.slice(1))})`);
  }
  add('}');
  add();
  add('public extension CGFloat {');
  for (const t of dims) {
    add(`    static let hc${pascal(t.path)}: CGFloat = CGFloat(HCTokens.Dimensions.${camel(t.path)})`);
  }
  add('}');
  add();
  add('public extension HCTokens {');
  add('    /// True when a font with this PostScript name is registered (bundled under UIAppFonts or');
  add('    /// registered with CTFontManager). Font.custom silently falls back to SF Pro when it is not,');
  add('    /// which would lose the monospaced fallback — so Font(hcStyle:) checks first.');
  add('    static func isFontRegistered(_ postScriptName: String) -> Bool {');
  add('        #if canImport(UIKit)');
  add('        return UIFont(name: postScriptName, size: 12) != nil');
  add('        #elseif canImport(AppKit)');
  add('        return NSFont(name: postScriptName, size: 12) != nil');
  add('        #else');
  add('        return false');
  add('        #endif');
  add('    }');
  add('}');
  add();
  add('public extension Font {');
  add('    /// A Dynamic Type font from a token style (scales with the user\'s text size). Bundled faces go');
  add('    /// through Font.custom(_:size:relativeTo:); if the face isn\'t registered, the SF fallback is used');
  add('    /// (SF Mono for mono and hero, SF Pro otherwise). Pass `boldText` from');
  add('    /// `@Environment(\\.legibilityWeight) == .bold`: system fonts embolden themselves, bundled faces');
  add('    /// step up to the next heavier face (+200).');
  add('    init(hcStyle s: HCTokens.TextStyle, boldText: Bool = false) {');
  add('        let style: Font.TextStyle');
  add('        switch s.textStyle {');
  for (const [k, v] of Object.entries(TEXT_STYLES)) add(`        case "${k}": style = ${v}`);
  add('        default: style = .body');
  add('        }');
  add('        let weight: Font.Weight');
  add('        switch s.weight {');
  for (const [k, v] of Object.entries(WEIGHTS)) add(`        case ${k}: weight = ${v}`);
  add('        default: weight = .regular');
  add('        }');
  add('        if let face = s.family.face(weight: s.weight + (boldText ? 200 : 0)), HCTokens.isFontRegistered(face) {');
  add('            self = Font.custom(face, size: s.size, relativeTo: style)');
  add('            return');
  add('        }');
  add('        let design: Font.Design = s.family.fallbackMonospaced || s.monospaced ? .monospaced : .default');
  add('        let font = Font.system(style, design: design, weight: weight)');
  add('        self = s.monospaced ? font.monospacedDigit() : font');
  add('    }');
  add();
  add('    // Computed, not stored: the registration check runs on each use, so fonts registered at launch');
  add('    // with CTFontManager are picked up even if a token font was read before registration.');
  for (const t of types) {
    add(doc(t, '    ').trimEnd() || undefined);
    add(`    static var hc${pascal(t.path.slice(1))}: Font { Font(hcStyle: HCTokens.Typography.${camel(t.path.slice(1))}) }`);
  }
  add('}');
  add();
  add('public extension Animation {');
  add('    /// A token motion; pass `@Environment(\\.accessibilityReduceMotion)`.');
  add('    static func hc(_ m: HCTokens.Motion, reduceMotion: Bool) -> Animation {');
  add('        .timingCurve(m.c1x, m.c1y, m.c2x, m.c2y, duration: m.duration(reduceMotion: reduceMotion))');
  add('    }');
  for (const g of motionGroups) {
    add(`    static func hc${pascal([g])}(reduceMotion: Bool) -> Animation { hc(HCTokens.Motions.${camel([g])}, reduceMotion: reduceMotion) }`);
  }
  add('}');
  add();
  add('public extension Material {');
  for (const t of materials) {
    const ios = t.raw[ref].ios;
    if (!/^(ultraThin|thin|regular|thick|ultraThick|bar)Material$/.test(ios)) throw new Error(`${t.key}: unknown material ${ios}`);
    add(doc(t, '    ').trimEnd() || undefined);
    add(`    static var hc${pascal(t.path.slice(1))}: Material { .${ios.replace(/Material$/, '')} }`);
  }
  add('}');
  add();
  add('public extension View {');
  add('    /// Applies a token elevation shadow.');
  add('    func hcShadow(_ s: HCTokens.Shadow) -> some View {');
  add('        shadow(color: Color(.sRGB, red: Double(s.color.red) / 255, green: Double(s.color.green) / 255, blue: Double(s.color.blue) / 255, opacity: Double(s.color.alpha) / 255), radius: s.blur / 2, x: s.x, y: s.y)');
  add('    }');
  add('}');
  add('#endif');
  add();

  // ---------- Haptics ----------
  const cases = haptics.map((t) => camel(t.path.slice(1)));
  add('/// When to play a haptic. Never the only feedback — each has a visual change too.');
  add('public enum HCHaptic: CaseIterable, Sendable {');
  add(`    case ${cases.join(', ')}`);
  add();
  add('    public var token: HCTokens.Haptic {');
  add('        switch self {');
  for (const c of cases) add(`        case .${c}: HCTokens.Haptics.${c}`);
  add('        }');
  add('    }');
  add('}');
  add();
  add('#if canImport(UIKit) && !os(watchOS) && !os(tvOS)');
  add('import UIKit');
  add();
  add('public extension HCHaptic {');
  add('    @MainActor func play() {');
  add('        let t = token');
  add('        switch t.generator {');
  add('        case .impact:');
  add('            let style: UIImpactFeedbackGenerator.FeedbackStyle');
  add('            switch t.style {');
  add('            case "light": style = .light');
  add('            case "heavy": style = .heavy');
  add('            case "soft": style = .soft');
  add('            case "rigid": style = .rigid');
  add('            default: style = .medium');
  add('            }');
  add('            UIImpactFeedbackGenerator(style: style).impactOccurred()');
  add('        case .notification:');
  add('            let type: UINotificationFeedbackGenerator.FeedbackType');
  add('            switch t.style {');
  add('            case "success": type = .success');
  add('            case "warning": type = .warning');
  add('            default: type = .error');
  add('            }');
  add('            UINotificationFeedbackGenerator().notificationOccurred(type)');
  add('        case .selection:');
  add('            UISelectionFeedbackGenerator().selectionChanged()');
  add('        }');
  add('    }');
  add('}');
  add('#elseif os(watchOS)');
  add('import WatchKit');
  add();
  add('public extension HCHaptic {');
  add('    /// The nearest WKHapticType: impacts and selection click, notifications map to success / retry / failure.');
  add('    @MainActor func play() {');
  add('        let t = token');
  add('        let type: WKHapticType');
  add('        switch (t.generator, t.style) {');
  add('        case (.notification, "success"): type = .success');
  add('        case (.notification, "warning"): type = .retry');
  add('        case (.notification, _): type = .failure');
  add('        case (.impact, "heavy"), (.impact, "rigid"): type = .start');
  add('        default: type = .click');
  add('        }');
  add('        WKInterfaceDevice.current().play(type)');
  add('    }');
  add('}');
  add('#endif');

  return L.filter((l) => l !== undefined).join('\n') + '\n';
}
